use xiom.io;
interface Logger {
  fn log(msg: Str);
}

type ConsoleLogger = {
  prefix: Str;
}

fn ConsoleLogger.log(self, msg: Str) {
  io.println(self.prefix + ": " + msg);
}

type SilentLogger = {
}

fn SilentLogger.log(self, msg: Str) {
}

fn do_work[T: Logger](logger: &T) {
  logger.log("Work started");
  logger.log("Work done");
}

fn main() -> Int {
  let console = ConsoleLogger{ prefix: "INFO" };
  let silent = SilentLogger{};

  do_work(&console);
  do_work(&silent);
  return 0;
}
